//! 🧪️ Real fallible UTF-8 birth keeps the same String through all denials and a null allocator result.
use super::*;
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
#[test]fn shared_utf8_birth_null_retry_alias_and_paid_close_preserve_original_bytes(){
 let f:serde_json::Value=serde_json::from_str::<serde_json::Value>(include_str!("../../../📦️paged/🎮️append/🎟️work/📐️.json")).unwrap()["sharedUtf8"].clone();let stock=&f["stock"];let mut left=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut fuel=stock["fuel"].as_u64().unwrap();let g=|left:RetainedCloneGrant|RetainedCloneGrant{maximum_items:left.maximum_items.min(1),maximum_copy_bytes:left.maximum_copy_bytes.min(4096),maximum_capacity_bytes:left.maximum_capacity_bytes.min(65536),maximum_release_bytes:left.maximum_release_bytes.min(65536),maximum_depth:left.maximum_depth};let debit=|left:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,w:u64|{assert!(p.fits(*left));left.maximum_items-=p.copied_items;left.maximum_copy_bytes-=p.copied_bytes;left.maximum_capacity_bytes-=p.retained_capacity_bytes;left.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(w).unwrap();};let mut input=f["text"].as_str().unwrap().to_owned();let pointer=input.as_ptr();
 let grant=g(left);for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:0,..grant}]{let(turn,heap)=observe(||SharedUtf8::admit(input,denied));assert_eq!(turn.work,0);assert_eq!(heap,(0,0));let(_,returned)=turn.result.unwrap_err();input=returned;assert_eq!(input.as_ptr(),pointer);assert_eq!(serde_json::to_value(&input).unwrap(),f["text"]);}
 let((turn,attempts),heap)=observe(||refuse(||SharedUtf8::admit(input,g(left))));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let(error,returned)=turn.result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::AllocationFailed);debit(&mut left,&mut fuel,error.retained_progress(),turn.work);input=returned;assert_eq!(input.as_ptr(),pointer);
 let(turn,heap)=observe(||SharedUtf8::admit(input,g(left)));assert_eq!(turn.work,1);let(owner,p)=turn.result.unwrap();assert_eq!(p.copied_bytes,0);assert_eq!(heap,(p.retained_capacity_bytes,0));debit(&mut left,&mut fuel,p,turn.work);assert_eq!(owner.as_ptr(),pointer);assert_eq!(serde_json::to_value(&owner).unwrap(),f["text"]);assert_eq!(Arc::strong_count(owner.0.as_ref().unwrap()),1);
 let(turn,heap)=observe(||owner.admit_clone(g(left)));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));let(alias,p)=turn.result.unwrap();debit(&mut left,&mut fuel,p,turn.work);assert_eq!(alias.as_ptr(),pointer);assert_eq!(Arc::strong_count(owner.0.as_ref().unwrap()),2);
 let mut owners=crate::retirement::controlled::ControlledRetirement::new((owner,alias)).ok().unwrap();debit(&mut left,&mut fuel,RetainedCloneProgress{copied_items:1,..Default::default()},1);for _ in 0..100000{if owners.terminal_is_empty(){break}let result=owners.step(g(left));let work=owners.last_turn_work();let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());debit(&mut left,&mut fuel,p,work);result.unwrap();}assert!(owners.terminal_is_empty());
}
